connect SYS/change_on_install as SYSDBA
set echo on
spool logs\CreateDBFiles.log
CREATE TABLESPACE "DRSYS" LOGGING DATAFILE '$(EW_ORACLE_BASE)\oradata\$(EW_ORACLE_SID)\drsys01.dbf' SIZE 20M REUSE AUTOEXTEND ON NEXT  640K MAXSIZE UNLIMITED EXTENT MANAGEMENT LOCAL SEGMENT SPACE MANAGEMENT  AUTO ;
CREATE TABLESPACE "INDX" LOGGING DATAFILE '$(EW_ORACLE_BASE)\oradata\$(EW_ORACLE_SID)\indx01.dbf' SIZE 25M REUSE AUTOEXTEND ON NEXT  1280K MAXSIZE UNLIMITED EXTENT MANAGEMENT LOCAL SEGMENT SPACE MANAGEMENT  AUTO ;
CREATE TABLESPACE "TOOLS" LOGGING DATAFILE '$(EW_ORACLE_BASE)\oradata\$(EW_ORACLE_SID)\tools01.dbf' SIZE 10M REUSE AUTOEXTEND ON NEXT  320K MAXSIZE UNLIMITED EXTENT MANAGEMENT LOCAL SEGMENT SPACE MANAGEMENT  AUTO ;
CREATE TABLESPACE "USERS" LOGGING DATAFILE '$(EW_ORACLE_BASE)\oradata\$(EW_ORACLE_SID)\users01.dbf' SIZE 25M REUSE AUTOEXTEND ON NEXT  1280K MAXSIZE UNLIMITED EXTENT MANAGEMENT LOCAL SEGMENT SPACE MANAGEMENT  AUTO ;
CREATE TABLESPACE "XDB" LOGGING DATAFILE '$(EW_ORACLE_BASE)\oradata\$(EW_ORACLE_SID)\xdb01.dbf' SIZE 20M REUSE AUTOEXTEND ON NEXT  640K MAXSIZE UNLIMITED EXTENT MANAGEMENT LOCAL SEGMENT SPACE MANAGEMENT  AUTO ;
spool off
exit;
